'use strict';
class EchoSheetAccountService extends EchoAccountService {
 constructor(config,factory){super(config,factory);this.sheetMode=config?.accountBackend==='sheets';this.recoveryToken=null;this.sheetSessionKey='echo-sheets-session';this.authEpoch=0}
 get configured(){if(!this.sheetMode)return super.configured;return /^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(this.config.appsScriptUrl||'')}
 async request(action,body={},anonymous=false){const token=this.session?.token,uid=this.user?.id;if(!anonymous&&!token)throw Error('请先登录账号。');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),45000);try{const response=await fetch(this.config.appsScriptUrl,{method:'POST',headers:{'Content-Type':'text/plain;charset=UTF-8'},body:JSON.stringify({action,...body,...(!anonymous?{session_token:token}:{})}),redirect:'follow',signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('账号服务暂时不可用，请稍后重试。');const result=await response.json();if(!anonymous&&(this.user?.id!==uid||this.session?.token!==token))throw Error('登录状态已改变。');if(!result.ok){const messages={UNAUTHORIZED:'登录已过期，请重新登录。',INVALID_EMAIL:'请输入有效邮箱。',INVALID_PASSWORD:'新密码需为 12–256 个字符。',INVALID_CREDENTIALS:'邮箱或密码不正确。旧账号迁移后请先重设密码。',EMAIL_NOT_VERIFIED:'请先确认邮箱后登录。',TOKEN_INVALID:'邮件链接已失效或已使用，请重新申请。',RATE_LIMITED:'操作次数较多，请稍后重试。',EMAIL_LIMIT:'邮件发送暂不可用，请稍后重试。',ACCOUNT_INACTIVE:'账号当前不可用。',MIGRATION_NOT_ACTIVE:'新账号服务尚未启用，请稍后重试。',FORBIDDEN:'没有权限执行此操作。',HANDLE_TAKEN:'这个用户名已被使用。',INVALID_PROFILE:'请检查昵称和用户名。',FRIENDS_REQUIRED:'双方确认好友后才能操作。',FRIENDSHIP_EXISTS:'已有好友关系或好友申请。',CURRENT_PASSWORD_REQUIRED:'当前密码不正确。',ADMIN_REQUIRED:'仅管理员可操作。',USER_NOT_FOUND:'未找到该用户。',AVATAR_STORAGE_UNAVAILABLE:'头像服务暂不可用，请重试。',VALUE_TOO_LARGE:'内容太长，请减少后重试。',INVALID_PLAYLIST:'歌单资料无效或超过容量限制。',MESSAGE_CONFLICT:'消息编号已被使用，请重新发送。'};const error=Object.assign(Error(messages[result.error]||'操作失败，请重试。'),{code:result.error});if(result.error==='UNAUTHORIZED'){this.applySession(null,'SIGNED_OUT')}throw error}return result}catch(error){if(error.name==='AbortError')throw Error('连接超时，请重试。');if(['SyntaxError','TypeError'].includes(error.name))throw Error('账号服务暂时不可用，请稍后重试。');throw error}finally{clearTimeout(timeout)}}
 applySession(session,event='SIGNED_IN'){this.authEpoch++;const previous=this.user?.id;this.session=session;if(previous!==this.user?.id){this.profile=null;this.entitlement=null;this.isAdmin=false;this.avatarCache.clear()}try{if(session)localStorage.setItem(this.sheetSessionKey,JSON.stringify(session));else localStorage.removeItem(this.sheetSessionKey)}catch{}this.dispatchEvent(new CustomEvent('session',{detail:{event,user:this.user}}))}
 async init(){if(!this.sheetMode)return super.init();if(!this.configured)throw Error('账号服务尚未连接。');this.client={};const hash=new URLSearchParams(location.hash.slice(1)),purpose=hash.get('echo-auth'),token=hash.get('token');if(['reset','verify'].includes(purpose)&&/^[a-f0-9]{64}$/i.test(token||'')){history.replaceState(null,'',location.pathname+location.search);if(purpose==='reset'){this.recoveryToken=token;this.dispatchEvent(new CustomEvent('session',{detail:{event:'PASSWORD_RECOVERY'}}));return}await this.request('auth.verify',{token},true);this.dispatchEvent(new CustomEvent('session',{detail:{event:'EMAIL_VERIFIED'}}));return}let session;try{session=JSON.parse(localStorage.getItem(this.sheetSessionKey)||'null')}catch{}if(session?.token&&session?.user?.id&&Date.parse(session.expires_at)>Date.now()){this.session=session;try{const result=await this.request('auth.session');this.profile=result.profile;this.entitlement=result.account;this.isAdmin=result.isAdmin;this.dispatchEvent(new CustomEvent('session',{detail:{event:'INITIAL_SESSION',user:this.user}}))}catch(error){if(error.code!=='UNAUTHORIZED')throw error}}else this.applySession(null,'SIGNED_OUT')}
 async signUp(email,password){if(!this.sheetMode)return super.signUp(email,password);return this.request('auth.register',{email,password,redirect:this.redirectURL()},true)}
 async signIn(email,password){if(!this.sheetMode)return super.signIn(email,password);const epoch=++this.authEpoch,result=await this.request('auth.signin',{email,password},true);if(epoch!==this.authEpoch)throw Error('登录状态已改变。');this.applySession(result.session);this.flush();return result}
 async signOut(){if(!this.sheetMode)return super.signOut();this.authEpoch++;if(this.session?.token)await this.request('auth.signout');this.applySession(null,'SIGNED_OUT')}
 async resetPassword(email){if(!this.sheetMode)return super.resetPassword(email);await this.request('auth.reset.request',{email,redirect:this.redirectURL()},true)}
 async updatePassword(password,currentPassword){if(!this.sheetMode)return super.updatePassword(password,currentPassword);if(this.recoveryToken){const epoch=this.authEpoch;await this.request('auth.reset.complete',{token:this.recoveryToken,password},true);if(epoch!==this.authEpoch)throw Error('登录状态已改变。');this.recoveryToken=null;this.applySession(null,'SIGNED_OUT')}else await this.request('auth.password',{password,current_password:currentPassword||''})}
 async ensureProfile(){if(!this.sheetMode)return super.ensureProfile();const uid=this.requireUser(),result=await this.request('profile.get');if(this.user?.id===uid){this.profile=result.profile;await this.attachAvatars([result.profile])}return result.profile}
 async updateProfile(handle,display_name){if(!this.sheetMode)return super.updateProfile(handle,display_name);const result=await this.request('profile.update',{handle,display_name});this.profile=result.profile;await this.attachAvatars([this.profile]);return this.profile}
 async syncAdmin(){if(!this.sheetMode)return super.syncAdmin();const result=await this.request('account.get');this.entitlement=result.account;this.isAdmin=result.isAdmin;this.adminConnected=true;return result.account}
 async checkAdmin(){if(!this.sheetMode)return super.checkAdmin();await this.syncAdmin();return this.isAdmin}
 async library(){if(!this.sheetMode)return super.library();const result=await this.request('library.get');return{likes:result.likes,playlists:result.playlists}}
 async flush(){if(!this.sheetMode)return super.flush();if(!this.user||this.flushing)return;this.flushing=true;const uid=this.user.id;try{while(this.user?.id===uid){const [key,op]=Object.entries(this.pending(uid))[0]||[];if(!key)break;if(op.type==='like')await this.request('likes.set',{track:op.track,liked:op.liked});else if(op.type==='playlist')await this.request('playlist.save',{id:op.id,name:op.name,cover:op.cover||'',visibility:op.visibility||'private',tracks:op.tracks});else await this.request('playlist.delete',{id:op.id});if(this.user?.id!==uid)break;const pending=this.pending(uid);if(pending[key]?.sequence===op.sequence)delete pending[key];this.lastSyncError=null;this.savePending(uid,pending)}}catch(error){if(this.user?.id===uid){this.lastSyncError=error.message;this.dispatchEvent(new CustomEvent('sync',{detail:{pending:Object.keys(this.pending(uid)).length,error:error.message}}))}}finally{this.flushing=false;if(this.user&&this.user.id!==uid)this.flush()}}
 async searchPeople(query){if(!this.sheetMode)return super.searchPeople(query);const result=await this.request('people.search',{query:query.toLowerCase()});await this.attachAvatars(result.people);return result.people}
 async friends(){if(!this.sheetMode)return super.friends();const result=await this.request('friends.list');await this.attachAvatars(result.friends.map(row=>row.person));return result.friends}
 async requestFriend(person_id){if(!this.sheetMode)return super.requestFriend(person_id);await this.request('friends.request',{person_id})}
 async acceptFriend(id){if(!this.sheetMode)return super.acceptFriend(id);await this.request('friends.accept',{id})}
 async removeFriend(id){if(!this.sheetMode)return super.removeFriend(id);await this.request('friends.remove',{id})}
 async sharedPlaylists(person_id){if(!this.sheetMode)return super.sharedPlaylists(person_id);return(await this.request('playlist.shared',{person_id})).playlists}
 async messages(person_id,cursor=null){if(!this.sheetMode)return super.messages(person_id,cursor);return(await this.request('messages.read',{person_id,cursor})).messages}
 async sendMessage(person_id,body='',track=null,id=crypto.randomUUID()){if(!this.sheetMode)return super.sendMessage(person_id,body,track,id);const music=track?EchoMusicLibrary.share(track):null;if(track&&!music)throw Error('这首歌曲暂不支持直接分享。');return(await this.request('messages.send',{person_id,body:String(body).trim(),track:music,id})).message}
 async attachAvatars(people){if(!this.sheetMode)return super.attachAvatars(people);const uid=this.user?.id,paths=[...new Set(people.map(row=>row.avatar_path).filter(Boolean))],missing=paths.filter(path=>!this.avatarCache.has(path)||this.avatarCache.get(path).expires<Date.now());if(missing.length){for(let i=0;i<missing.length;i+=50){const result=await this.request('avatar.sign',{paths:missing.slice(i,i+50)});if(this.user?.id!==uid)return people;for(const row of result.urls||[])if(row.signedUrl)this.avatarCache.set(row.path,{url:row.signedUrl,expires:Date.now()+3500000})}}if(this.user?.id===uid)for(const person of people)person.avatar_url=this.avatarCache.get(person.avatar_path)?.url||null;return people}
 async uploadAvatar(blob){if(!this.sheetMode)return super.uploadAvatar(blob);const uid=this.requireUser();if(this.avatarUploading)throw Error('照片正在上传，请稍候。');if(blob.type!=='image/jpeg'||blob.size>1048576)throw Error('请选择已处理的 JPEG 照片。');this.avatarUploading=true;try{const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob)});if(this.user?.id!==uid)throw Error('登录状态已改变。');const result=await this.request('avatar.upload',{image});this.profile=result.profile;await this.attachAvatars([this.profile]);return this.profile}finally{this.avatarUploading=false}}
 async removeAvatar(){if(!this.sheetMode)return super.removeAvatar();const result=await this.request('avatar.remove');this.profile=result.profile;return this.profile}
 async adminRequest(body){if(!this.sheetMode)return super.adminRequest(body);const {action,...rest}=body;return this.request('admin.'+action,rest)}
 async deleteAccount(){if(!this.sheetMode)return super.deleteAccount();const uid=this.requireUser();await this.request('auth.delete');this.dispatchEvent(new CustomEvent('deleted',{detail:{id:uid}}));this.applySession(null,'SIGNED_OUT')}
}
globalThis.EchoSheetAccountService=EchoSheetAccountService;
